import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"31、【鹹】 艮下兌上","description":"周易闡真 - 31、【鹹】 艮下兌上","frontmatter":{"title":"31、【鹹】 艮下兌上","description":"周易闡真 - 31、【鹹】 艮下兌上"},"headers":[],"relativePath":"classics/chanzhen/032.md","filePath":"classics/chanzhen/032.md"}'),s={name:"classics/chanzhen/032.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：鹹，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平；觀其所感，而天地萬物之情可見矣！</p></blockquote><h1 id="_31、【鹹】-艮下兌上" tabindex="-1">31、【鹹】 艮下兌上 <a class="header-anchor" href="#_31、【鹹】-艮下兌上" aria-label="Permalink to “31、【鹹】 艮下兌上”">​</a></h1><p>初六：鹹其拇。</p><p>六二：鹹其腓，兇，居吉。</p><p>九三：鹹其股，執其隨，往吝。</p><p>九四：貞吉，悔亡。憧憧往來，朋從爾思。</p><p>九五：鹹其脢，無悔。</p><p>上六：鹹其輔頰舌。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山上有澤，鹹。君子以虛受人。</p><p>鹹者，感也。上兌澤，下艮山，是山上有澤也。澤本虛，山本高，高而能虛，鹹之象也。</p><p>君子有見於此，知山上不虛，不能有澤；人心不虛，不能感物。以是虛其己之所有，而受益於人焉。紫陽雲：“休施巧偽為功力，認取他家不死方。”他者，人也。人非世間之凡人，乃我本來不死之真人，因交後天，走於兌家，掩埋已久，迷而不返。間或一顧，學者執著後天，當面錯過，不能受之。此其故，皆由不能煉己。不能煉己，私慾滿腔，茅塞靈竅，實而不虛，總有人來，無處容納。修道君子，煉己持心，除去一切後有滓質，而心虛矣。心虛，則先天之氣自虛無中來，即能受人之益而實其腹。我以虛感，彼以實應，小往而大來，金丹自然凝結，亦如高山，上虛受澤之潤，有不期然而然者。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>拇，茂後反。腓，音肥。憧，音同。脢，音枚。頰，音劫。</p><p>鹹者，感也。卦德上兌悅，下艮止，剛止於內，柔悅於外，悅以止為體，止以悅為用，有陰陽相應之義，故謂鹹。此調和陰陽之卦，承上坎卦而來。坎者，陰陷其陽，陽不健而陰不順，陰陽不交，此調和之功不可缺。但調和陰陽，貴乎自然，不貴乎勉強。自然者，無心之感也。勉強者，有心之感也。無心之感，陰陽相和，鹹無不感；有心之感，陰陽各別，感之有限，故鹹有亨道也。鹹道雖亨，然無心有無心之是非，有心有有心之是非，不得以枯木寒灰之無心，即謂鹹之亨道。枯木寒灰，純陰無陽，何得謂感？所謂感者，陰陽潛通之義，如卦象少男少女同處，彼此無心，及至陰陽氣足，彼此情動，自然相感。此不感之感，何得以蠢然無心為感乎?</p><p>所謂無心者，無人心也。無人心即有道心，道心是心非心。所謂有心者，有人心也。有人心即無道心，人心非心是心。道心為真，人心為假。用假心則感之不正，陰陽兩離；用真心則感之得正，陰陽相通。或陰感而陽應，或陽感而陰應，均以道心為主。以正而感，感以正，而不感以心，何物不可感，何感不能利乎？</p><p>天下感之以正者，莫如貞女。女德主乎貞靜，不輕失身於人，必待其佳配而有感。此感之不以心而以正，卦德先止後悅，悅本於止之所由來也。</p><p>修道者，調和陰陽，使陰陽感通，能取貞女之德以為感，則所感皆正，寂然不動，感而遂通。感而遂通，寂然不動，止於其所，逆之順之，無不遂心如意而得其吉矣。</p><p>初六，性愚志劣，不能煉己持心，妄想大事，如鹹其拇矣。拇為足大趾，能動不能行之物，不能行而感之，感不得其正。此動人心之感也。</p><p>六二，柔而無剛，內無道心，為人心所感，如感其腓矣。腓為足肚，宜靜不宜動之物。不宜動而妄動，動必招兇。然柔順得中，雖有人心感動，能居於正，不為人心所感，亦兇中致吉之道。此無道心之感也。</p><p>九三，陽剛宜守道心，不可因外物而動人。心者乃剛而不中，見景生情，如感其股矣。感之於股，不能止於其所，隨風起塵，執守不專，有道心而又生人心，以是往而行道，未免見羞於大方。此失道心之感也。</p><p>九四，陽剛本有道心，似乎貞而得吉，又剛而能柔，無感亦無所害，似乎有悔可亡，乃有應。初陰為私慾所牽，道心中又雜人心，外無感而內有感，故憧憧往來，朋從爾思也。朋從之思，因人心而昧道心，性亂情迷，一身皆為人心所搖動。此起人心又昧道心之感也。</p><p>九五，在上陰下陽之際，執兩用中，道心常存，人心不生，因物付物，皆出無心，如感其脢矣。脢為背肉，在心之上，近心而離心。道心人心所隔者，毫髮之間，感之於脢，雖近於心，而實非心，非心之心，是謂真心。真心非色非空，無方無所，虛靈不昧，是謂無心。以無心感有心，雖有心亦歸於無心，無心無悔，渾然天理，止於至善之地，而不遷矣。此守道心而無人心之感也。</p><p>上六，在鹹之終，又在悅之極，順其所欲，務外失內，巧言令色，一切是假，是謂鹹其輔頰舌也。凡口、言、笑三者皆動，口動而心未有不動者。此絕無道心全用人心之感也。</p><p>六爻皆有感道，或以人心感，或以道心感，或有道心而又感於人心，或揹人心而只感以道心，是非不等，惟止於至善而感之，則道心常存，人心永滅，真陰真陽，隔礙潛通，如磁石吸鐵，金丹自虛無中結就矣。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
